// The JSON-LD block that tells a search engine the home page is a free web
// application. Text for a <script type="application/ld+json"> element.
//
// Hand-rolled rather than generated by Next from a page's head-tag export, so
// nothing else would leave the address out when the build cannot know it: see
// lib/siteUrl.ts for why the image published for self-hosters must claim no
// origin at all.
//
// Pure, so vitest can cover it. The home page renders it (app/page.tsx) and
// no other route does.

// "<" as JSON's own escape for it. A JSON parser reads the same string, and
// the HTML parser no longer sees a tag: the address comes from a build
// setting, and "</script>" in it would otherwise end the element.
const LESS_THAN = '\\' + 'u003c';

/** The serialized block. `url` is this deployment's public origin, or
 *  undefined when it is unknowable, in which case the field is omitted. */
export function webApplicationJsonLd(url: string | undefined): string {
    return JSON.stringify({
        '@context': 'https://schema.org',
        '@type': 'WebApplication',
        name: 'Floe',
        ...(url && { url }),
        description: 'Secure, encrypted P2P file transfer. No accounts, no file storage, no registration required.',
        applicationCategory: 'UtilitiesApplication',
        operatingSystem: 'Any',
        offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
        browserRequirements: 'Requires a modern browser with WebRTC support',
    }).replace(/</g, LESS_THAN);
}
